const manifest = {
  crews: {
    catalog: { topology: 'sequential', agents: ['researcher', 'writer', 'reviewer'] },
    pricing: { topology: 'managed', agents: ['analyst', 'approver'], gate: 'amount>100' },
    support: { topology: 'subgraph', ref: 'returns-graph-v1' },
  },
};
const checks = [
  ['three crews', Object.keys(manifest.crews).length === 3],
  ['managed has gate', !!manifest.crews.pricing.gate],
  ['support reuses subgraph', manifest.crews.support.topology === 'subgraph'],
  ['catalog fixed pipeline', manifest.crews.catalog.topology === 'sequential'],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'manifest sound' : 'manifest BROKEN');
